// Input Validation & Defaults
const inputData = $input.first().json;
const requestData = inputData.body || inputData;

// Validate required fields
if (!requestData.companies || !Array.isArray(requestData.companies)) {
  throw new Error('"companies" array is required');
}

if (requestData.companies.length === 0) {
  throw new Error('"companies" array cannot be empty');
}

// Validate each company has required fields
for (const company of requestData.companies) {
  if (!company.company_name) {
    throw new Error('Each company must have "company_name"');
  }
  if (!company.domain) {
    throw new Error('Each company must have "domain"');
  }
}

// Generate request ID for tracking
const requestId = `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Set defaults
const validatedData = {
  request_id: requestId,
  companies: requestData.companies,
  min_confidence_score: requestData.min_confidence_score || 85,
  enable_enrichment: requestData.enable_enrichment !== false,
  client_crm_endpoint: requestData.client_crm_endpoint || '',
  timestamp_start: new Date().toISOString(),
  total_companies: requestData.companies.length
};

console.log(`[${requestId}] Validated ${validatedData.total_companies} companies`);

return [{
  json: validatedData
}];

// Email Pattern Generator
const items = $input.all();
const allEmails = [];

for (const item of items) {
  const company = item.json.company_name || '';
  const domain = item.json.domain || '';
  const firstNames = item.json.first_names || ['contact', 'info', 'hr'];
  const lastNames = item.json.last_names || ['team', 'dept'];
  const jobTitles = item.json.job_titles || ['HR Manager', 'Recruiter'];

  // Extract common patterns from Hunter response if available
  const hunterData = item.json.data || {};
  const commonPattern = hunterData.pattern || '{first}.{last}';

  // Generate email candidates for each first/last name combination
  for (const firstName of firstNames) {
    for (const lastName of lastNames) {
      const fn = firstName.toLowerCase();
      const ln = lastName.toLowerCase();
      const fi = fn.charAt(0);
      const li = ln.charAt(0);

      // 8 common email patterns
      const patterns = [
        `${fn}.${ln}@${domain}`,
        `${fn}${ln}@${domain}`,
        `${fi}${ln}@${domain}`,
        `${fn}_${ln}@${domain}`,
        `${ln}.${fn}@${domain}`,
        `${fn}@${domain}`,
        `${ln}@${domain}`,
        `${fi}.${ln}@${domain}`
      ];

      // Add unique patterns to results
      for (const email of patterns) {
        allEmails.push({
          email: email,
          company: company,
          domain: domain,
          first_name: firstName,
          last_name: lastName,
          pattern: commonPattern,
          request_id: item.json.request_id
        });
      }
    }
  }

  // Also add generic company emails
  const genericEmails = ['hr', 'recruiting', 'jobs', 'careers', 'info', 'contact'];
  for (const generic of genericEmails) {
    allEmails.push({
      email: `${generic}@${domain}`,
      company: company,
      domain: domain,
      first_name: generic,
      last_name: 'team',
      pattern: 'generic',
      request_id: item.json.request_id
    });
  }
}

console.log(`Generated ${allEmails.length} candidate emails`);

return allEmails.map(emailData => ({ json: emailData }));

// Consensus Scoring Engine
const items = $input.all();
const results = [];

for (const item of items) {
  const email = item.json.email || '';
  const company = item.json.company || '';
  const domain = item.json.domain || '';

  // Extract verification results from each provider
  const hunterData = item.json.data || {};
  const neverBounceData = item.json;
  const debounceData = item.json;

  // Hunter scoring (0-35 points)
  let hunterScore = 0;
  let hunterValid = false;
  const hunterStatus = hunterData.status || 'unknown';
  const hunterAcceptAll = hunterData.accept_all || false;
  const hunterDisposable = hunterData.disposable || false;

  if (hunterStatus === 'valid') {
    hunterScore = 35;
    hunterValid = true;
  } else if (hunterStatus === 'webmail') {
    hunterScore = 25;
  } else if (hunterStatus === 'risky') {
    hunterScore = 10;
  }

  // NeverBounce scoring (0-35 points)
  let neverBounceScore = 0;
  let neverBounceValid = false;
  const nbResult = neverBounceData.result || 'unknown';

  if (nbResult === 'valid' || nbResult === 0) {
    neverBounceScore = 35;
    neverBounceValid = true;
  } else if (nbResult === 'catchall' || nbResult === 2) {
    neverBounceScore = 15;
  } else if (nbResult === 'unknown' || nbResult === 3) {
    neverBounceScore = 5;
  }

  // Debounce scoring (0-30 points)
  let debounceScore = 0;
  let debounceValid = false;
  const dbStatus = debounceData.debounce || debounceData.result || 'unknown';
  const dbDisposable = debounceData.disposable || false;

  if (dbStatus === 'Safe to Send' || dbStatus === 'ok') {
    debounceScore = 30;
    debounceValid = true;
  } else if (dbStatus === 'Risky') {
    debounceScore = 10;
  }

  // Calculate base score (0-100)
  let score = hunterScore + neverBounceScore + debounceScore;
  let validCount = [hunterValid, neverBounceValid, debounceValid].filter(v => v).length;

  // Apply penalties
  const isCatchAll = hunterAcceptAll || nbResult === 'catchall' || nbResult === 2;
  const isDisposable = hunterDisposable || dbDisposable;

  if (isCatchAll) {
    score -= 20;
  }
  if (isDisposable) {
    score -= 50;
  }

  // Ensure score is between 0-100
  score = Math.max(0, Math.min(100, score));

  // Determine deliverability
  const isDeliverable = score >= 85 && validCount >= 2 && !isDisposable;

  results.push({
    json: {
      email: email,
      company: company,
      domain: domain,
      confidence_score: score,
      verified_by_count: validCount,
      is_deliverable: isDeliverable,
      flags: {
        catch_all: isCatchAll,
        disposable: isDisposable
      },
      verification_details: {
        hunter: {
          status: hunterStatus,
          score: hunterScore,
          accept_all: hunterAcceptAll,
          disposable: hunterDisposable
        },
        neverbounce: {
          result: nbResult,
          score: neverBounceScore
        },
        debounce: {
          status: dbStatus,
          score: debounceScore,
          disposable: dbDisposable
        }
      },
      request_id: item.json.request_id,
      verified_at: new Date().toISOString()
    }
  });
}

console.log(`Scored ${results.length} emails`);

return results;

// Final JSON Formatter
const items = $input.all();
const formattedResults = [];

for (const item of items) {
  const enrichmentData = item.json.public_identifier ? {
    linkedin_url: item.json.public_identifier,
    full_name: item.json.full_name || '',
    headline: item.json.headline || '',
    current_company: item.json.experiences?.[0]?.company || '',
    current_title: item.json.experiences?.[0]?.title || '',
    location: item.json.city || '',
    profile_pic: item.json.profile_pic_url || ''
  } : null;

  formattedResults.push({
    json: {
      email: item.json.email,
      company: item.json.company,
      domain: item.json.domain,
      confidence_score: item.json.confidence_score,
      is_deliverable: item.json.is_deliverable,
      verified_by_count: item.json.verified_by_count,
      quality_tag: item.json.confidence_score >= 95 ? 'Premium' : 'Good',
      flags: item.json.flags,
      verification_details: item.json.verification_details,
      enrichment: enrichmentData,
      verified_at: item.json.verified_at,
      request_id: item.json.request_id
    }
  });
}

return formattedResults;

// Quality Tagger
const items = $input.all();

for (const item of items) {
  const score = item.json.confidence_score || 0;

  if (score >= 95) {
    item.json.quality_tag = 'Premium';
  } else if (score >= 85) {
    item.json.quality_tag = 'Good';
  } else {
    item.json.quality_tag = 'Review';
  }
}

return items;

