// Global Error Handler
try {
  const errorData = $input.first().json;
  const error = errorData.error || $executionError || {};

  const errorLog = {
    timestamp: new Date().toISOString(),
    workflow: 'Email Verification Pipeline',
    error_message: error.message || 'Unknown error',
    error_stack: error.stack || '',
    node_name: error.node?.name || 'Unknown',
    request_id: errorData.request_id || 'unknown',
    severity: 'high'
  };

  console.error('[ERROR]', JSON.stringify(errorLog, null, 2));

  // Return error response
  return [{
    json: {
      success: false,
      error: error.message || 'Workflow execution failed',
      timestamp: new Date().toISOString(),
      request_id: errorData.request_id || 'unknown'
    }
  }];

} catch (handlerError) {
  console.error('[CRITICAL] Error handler failed:', handlerError);
  return [{
    json: {
      success: false,
      error: 'Critical workflow failure',
      timestamp: new Date().toISOString()
    }
  }];
}
